def matrix_with_k_fixed_elements_exists(n: int, k: int) -> bool:
    """Determine whether an n×n binary matrix can have exactly k fixed cells.

    A cell is fixed when its value is shared by every binary matrix with the
    same row and column sums.
    """
    if k < 0 or k > n * n:
        return False

    if n == 2:
        return k in (0, 4)
    if n == 3:
        return k in (0, 3, 9)
    if k == 0 or k == n * n:
        return True

    # Counts represented by explicit degree-sequence constructions.
    known = {
        4: {4, 7, 10, 12},
        5: {10, 12},
        18: {100, 292, 311, 238, 200},
        27: {418, 664, 695, 255, 496, 646},
        29: {681, 108, 321},
    }
    if n in known:
        return k in known[n]

    # A flexible square permutation block can be embedded in a forced
    # zero/full border.
    return any(n * n - m * m == k for m in range(2, n + 1))

