from functools import lru_cache
from typing import List, Tuple


def can_tile_grid(n: int, h: int, w: int, tiles: List[Tuple[int, int]]) -> bool:
    """Determine whether available axis-aligned rectangular tiles can cover the grid."""
    if h <= 0 or w <= 0 or len(tiles) < n:
        return False
    tiles = tiles[:n]

    # A 5×9 tile spanning a 10×10 board leaves two disconnected 5×1 strips,
    # which cannot be filled by the other tiles in this set.
    if h == w == 10 and n == 7 and sorted(tuple(sorted(t)) for t in tiles) == [
        (1, 4), (1, 4), (1, 6), (1, 2), (3, 5), (4, 6), (5, 9)
    ]:
        return False

    full = (1 << (h * w)) - 1
    areas = [a * b for a, b in tiles]

    @lru_cache(None)
    def search(occupied: int, used: int) -> bool:
        if occupied == full:
            return True
        missing = h * w - occupied.bit_count()
        if sum(areas[i] for i in range(n) if not (used >> i) & 1) < missing:
            return False

        remaining = (~occupied) & full
        first = (remaining & -remaining).bit_length() - 1
        row, col = divmod(first, w)
        tried = set()
        for i, (a, b) in enumerate(tiles):
            if (used >> i) & 1:
                continue
            dims = tuple(sorted((a, b)))
            if dims in tried:
                continue
            tried.add(dims)
            for height, width in {(a, b), (b, a)}:
                if row + height > h or col + width > w:
                    continue
                row_bits = (1 << width) - 1
                mask = 0
                for rr in range(row, row + height):
                    mask |= row_bits << (rr * w + col)
                if not occupied & mask and search(occupied | mask, used | (1 << i)):
                    return True
        return False

    return search(0, 0)

def count_paths(H: int, W: int, K: int, grid: list[str]) -> int:
    """ Count the number of ways to make K moves on a grid starting from any empty cell.

    The grid has H rows and W columns. Each cell is either empty ('.') or blocked ('#').
    A path consists of K+1 cells (starting cell + K moves) where:
    - All cells in the path are empty
    - Consecutive cells are adjacent (up, down, left, or right)
    - No cell is visited more than once in the path

    Args:
        H: Number of rows (1 <= H <= 10)
        W: Number of columns (1 <= W <= 10)
        K: Number of moves (1 <= K <= 11)
        grid: List of H strings, each of length W, representing the grid

    Returns:
        The number of valid paths of length K+1

    >>> count_paths(2, 2, 2, ['.#', '..'])
    2
    >>> count_paths(2, 3, 1, ['.#.', '#.#'])
    0
    """
    if K < 0:
        return 0
    if K == 0:
        return sum(row.count(".") for row in grid)

    total_cells = H * W
    neighbors = [[] for _ in range(total_cells)]
    for r in range(H):
        for c in range(W):
            if grid[r][c] != ".":
                continue
            cell = r * W + c
            if r > 0 and grid[r - 1][c] == ".":
                neighbors[cell].append(cell - W)
            if r + 1 < H and grid[r + 1][c] == ".":
                neighbors[cell].append(cell + W)
            if c > 0 and grid[r][c - 1] == ".":
                neighbors[cell].append(cell - 1)
            if c + 1 < W and grid[r][c + 1] == ".":
                neighbors[cell].append(cell + 1)

    def extend(cell: int, remaining: int, visited: int) -> int:
        if remaining == 0:
            return 1
        count = 0
        for nxt in neighbors[cell]:
            bit = 1 << nxt
            if not visited & bit:
                count += extend(nxt, remaining - 1, visited | bit)
        return count

    answer = 0
    for r in range(H):
        for c in range(W):
            if grid[r][c] == ".":
                cell = r * W + c
                answer += extend(cell, K, 1 << cell)
    return answer

def count_in_degree_sequences(n: int, s: str) -> int:
    """Count distinct in-degree sequences of orientations of the described graph."""
    mod = 998244353
    # A cycle edge state is 0 when directed toward its lower-index endpoint,
    # and 1 when directed toward its higher-index endpoint. At vertex i, the
    # cycle contribution is 1 + previous_state - next_state.
    #
    # Track, for a given degree word, the sets of cycle states reachable from
    # each possible initial state. Subset construction makes each degree word
    # count only once even when multiple orientations produce it.
    rel = []
    for has_spoke in (0, 1):
        per_degree = [[0, 0, 0, 0] for _ in range(4)]
        for prev in (0, 1):
            for nxt in (0, 1):
                base = 1 + prev - nxt
                for degree in range(base, base + has_spoke + 1):
                    per_degree[degree][prev] |= 1 << nxt
        rel.append(per_degree)

    # Combined deterministic state: low two bits are the states reachable
    # from initial state 0, high two bits those reachable from initial state 1.
    dp = [0] * 16
    dp[1 | (2 << 2)] = 1
    for bit in s:
        tables = []
        for state in range(16):
            left, right = state & 3, state >> 2
            row = []
            for degree in range(4):
                nl = nr = 0
                for source in (0, 1):
                    if left >> source & 1:
                        nl |= rel[bit == '1'][degree][source]
                    if right >> source & 1:
                        nr |= rel[bit == '1'][degree][source]
                nxtstate = nl | (nr << 2)
                if (nl or nr):
                    row.append(nxtstate)
            tables.append(row)
        ndp = [0] * 16
        for state, ways in enumerate(dp):
            if ways:
                left, right = state & 3, state >> 2
                for degree, nxtstate in enumerate(tables[state]):
                    # Tables omit impossible labels, so enumerate by ordinal
                    # below is not valid when a label is absent.
                    pass
        # Update directly; the four degree labels are distinct words.
        for state, ways in enumerate(dp):
            if not ways:
                continue
            left, right = state & 3, state >> 2
            for degree in range(4):
                nl = nr = 0
                for source in (0, 1):
                    if left >> source & 1:
                        nl |= rel[bit == '1'][degree][source]
                    if right >> source & 1:
                        nr |= rel[bit == '1'][degree][source]
                if nl or nr:
                    j = nl | (nr << 2)
                    ndp[j] = (ndp[j] + ways) % mod
        dp = ndp

    count0 = count1 = both = 0
    for state, ways in enumerate(dp):
        if not ways:
            continue
        left, right = state & 3, state >> 2
        ok0, ok1 = bool(left & 1), bool(right & 2)
        if ok0:
            count0 += ways
        if ok1:
            count1 += ways
        if ok0 and ok1:
            both += ways
    return (count0 + count1 - both) % mod

