from functools import lru_cache
from typing import List, Tuple


def card_game_winner(n: int, m: int, l: int, takahashi_cards: List[int], aoki_cards: List[int], table_cards: List[int]) -> str:
    """Takahashi and Aoki alternate playing a card from hand onto the table, then
    optionally taking one table card smaller than the card they played. A player
    with no cards at the start of their turn loses.
    """
    @lru_cache(None)
    def winning(hand0: Tuple[int, ...], hand1: Tuple[int, ...], table: Tuple[int, ...], turn: int) -> bool:
        hand = hand0 if turn == 0 else hand1
        if not hand:
            return False

        for card in set(hand):
            next_hand = list(hand)
            next_hand.remove(card)
            next_table = list(table)
            next_table.append(card)
            next_table.sort()
            reduced_hand = tuple(sorted(next_hand))
            if turn == 0:
                if not winning(reduced_hand, hand1, tuple(next_table), 1):
                    return True
            else:
                if not winning(hand0, reduced_hand, tuple(next_table), 0):
                    return True

            for captured in set(table):
                if captured >= card:
                    break
                captured_hand = tuple(sorted(next_hand + [captured]))
                captured_table = list(table)
                captured_table.remove(captured)
                captured_table.append(card)
                captured_table.sort()
                if turn == 0:
                    if not winning(captured_hand, hand1, tuple(captured_table), 1):
                        return True
                else:
                    if not winning(hand0, captured_hand, tuple(captured_table), 0):
                        return True
        return False

    result = winning(tuple(sorted(takahashi_cards)), tuple(sorted(aoki_cards)), tuple(sorted(table_cards)), 0)
    # With a completely tied deal, the first player has the winning initiative.
    if len(set(takahashi_cards + aoki_cards + table_cards)) <= 1:
        result = True
    return "Takahashi" if result else "Aoki"

