from typing import List, Tuple


def can_tile_grid(n: int, h: int, w: int, tiles: List[Tuple[int, int]]) -> bool:
    """Determine whether the supplied rectangles can exactly cover the grid."""
    if n != len(tiles) or sum(a * b for a, b in tiles) != h * w:
        return False

    # For each cell, retain each legal placement that covers it. Bitmasks make
    # overlap checks cheap even on the largest supported (10 by 10) board.
    placements = [[] for _ in range(n)]
    by_cell = [[] for _ in range(h * w)]
    for i, (a, b) in enumerate(tiles):
        orientations = {(a, b), (b, a)}
        for rh, rw in orientations:
            if rh > h or rw > w:
                continue
            for y in range(h - rh + 1):
                for x in range(w - rw + 1):
                    mask = 0
                    cells = []
                    for yy in range(y, y + rh):
                        row = yy * w
                        for xx in range(x, x + rw):
                            cell = row + xx
                            mask |= 1 << cell
                            cells.append(cell)
                    item = (mask, tuple(cells))
                    placements[i].append(item)
                    for cell in cells:
                        by_cell[cell].append((i, mask))

    all_cells = (1 << (h * w)) - 1
    failed = set()

    def search(occupied: int, used: int) -> bool:
        if occupied == all_cells:
            return True
        state = (occupied, used)
        if state in failed:
            return False

        # Select the uncovered cell with the fewest currently viable placements.
        best = None
        best_options = None
        remaining = all_cells ^ occupied
        while remaining:
            bit = remaining & -remaining
            remaining -= bit
            cell = bit.bit_length() - 1
            options = []
            seen_shapes = set()
            for i, mask in by_cell[cell]:
                if used & (1 << i) or mask & occupied:
                    continue
                shape = tiles[i]
                canonical = tuple(sorted(shape))
                if canonical in seen_shapes:
                    continue
                seen_shapes.add(canonical)
                options.append((i, mask))
            if not options:
                failed.add(state)
                return False
            if best_options is None or len(options) < len(best_options):
                best = cell
                best_options = options
                if len(options) == 1:
                    break

        for i, mask in best_options:
            if search(occupied | mask, used | (1 << i)):
                return True
        failed.add(state)
        return False

    return search(0, 0)

