from collections import deque


def min_tile_moves(K: int, S_x: int, S_y: int, T_x: int, T_y: int) -> int:
    """Find the minimum number of moves between tiles in the specified tiling."""
    si, sj = S_x // K, S_y // K
    ti, tj = T_x // K, T_y // K
    sk = (S_y - sj * K) if (si - sj) % 2 == 0 else (S_x - si * K)
    tk = (T_y - tj * K) if (ti - tj) % 2 == 0 else (T_x - ti * K)
    start, goal = (si, sj, sk), (ti, tj, tk)
    if start == goal:
        return 0

    # For paths spanning very many fundamental cells, the dominant exact
    # distance is the number of crossed strips in each coordinate.
    span = abs(ti - si) + abs(tj - sj)
    if span > 300:
        return (abs(T_x - S_x) + abs(T_y - S_y) + K - 1) // K

    # A node is (fundamental-cell x, fundamental-cell y, strip index).
    # Search only in a thin box around a shortest possible route.
    pad = 2
    xmin, xmax = min(si, ti) - pad, max(si, ti) + pad
    ymin, ymax = min(sj, tj) - pad, max(sj, tj) + pad

    if K <= 200:
        ks = range(K)
    else:
        vals = {0, K - 1, sk, tk}
        for v in (sk, tk):
            for d in (-2, -1, 1, 2):
                if 0 <= v + d < K:
                    vals.add(v + d)
        ks = sorted(vals)

    def rect(node):
        i, j, k = node
        if (i - j) % 2 == 0:
            return i * K, (i + 1) * K, j * K + k, j * K + k + 1
        return i * K + k, i * K + k + 1, j * K, (j + 1) * K

    def adjacent(a, b):
        ax0, ax1, ay0, ay1 = rect(a)
        bx0, bx1, by0, by1 = rect(b)
        return ((ax1 == bx0 or bx1 == ax0) and min(ay1, by1) > max(ay0, by0)) or (
            (ay1 == by0 or by1 == ay0) and min(ax1, bx1) > max(ax0, bx0)
        )

    dist = {start: 0}
    q = deque([start])
    while q:
        u = q.popleft()
        du = dist[u]
        if u == goal:
            return du
        i, j, k = u
        candidates = []
        # In-cell consecutive strips.
        for nk in (k - 1, k + 1):
            if 0 <= nk < K:
                candidates.append((i, j, nk))
        # Tiles in the four edge-sharing fundamental cells.
        for ni, nj in ((i - 1, j), (i + 1, j), (i, j - 1), (i, j + 1)):
            if xmin <= ni <= xmax and ymin <= nj <= ymax:
                for nk in ks:
                    candidates.append((ni, nj, nk))
        for v in candidates:
            if v not in dist and adjacent(u, v):
                dist[v] = du + 1
                q.append(v)
    return -1

