def count_paths(W: int, H: int, L: int, R: int, D: int, U: int) -> int:
    """Count monotone paths whose visited lattice points avoid the hole."""
    MOD = 998244353
    nmax = W + H + 4
    fact = [1] * (nmax + 1)
    for i in range(1, nmax + 1):
        fact[i] = fact[i - 1] * i % MOD
    invfact = [1] * (nmax + 1)
    invfact[nmax] = pow(fact[nmax], MOD - 2, MOD)
    for i in range(nmax, 0, -1):
        invfact[i - 1] = invfact[i] * i % MOD

    def choose(n, k):
        if k < 0 or k > n:
            return 0
        return fact[n] * invfact[k] % MOD * invfact[n - k] % MOD

    # Sum C(i+j,i) over offsets 0<=i<=a, 0<=j<=b.
    def prefix(a, b):
        if a < 0 or b < 0:
            return 0
        return (choose(a + b + 2, a + 1) - 1) % MOD

    # Sum unrestricted path counts ending at every point in [0,a]x[0,b].
    def endpoint_sum(a, b):
        if a < 0 or b < 0:
            return 0
        return (choose(a + b + 4, b + 2) - (b + 3) - (a + 1) * (b + 2)) % MOD

    def rect_sum(f, x1, x2, y1, y2):
        return (f(x2, y2) - f(x1 - 1, y2) - f(x2, y1 - 1)
                + f(x1 - 1, y1 - 1)) % MOD

    all_paths = endpoint_sum(W, H)
    paths_ending_in_hole = rect_sum(endpoint_sum, L, R, D, U)
    result = (all_paths - paths_ending_in_hole) % MOD

    def ways_to(x, y):
        if x < 0 or y < 0:
            return 0
        return (choose(x + y + 2, x + 1) - 1) % MOD

    hit_paths = 0

    def add_first_entry(x, y, incoming):
        nonlocal hit_paths
        suffix = prefix(W - x, H - y)
        hole_suffix = (
            prefix(R - x, U - y)
            - prefix(L - x - 1, U - y)
            - prefix(R - x, D - y - 1)
            + prefix(L - x - 1, D - y - 1)
        ) % MOD
        hit_paths = (hit_paths + incoming * (suffix - hole_suffix)) % MOD

    # First entry on the left boundary of the hole.
    for y in range(D, U + 1):
        incoming = ways_to(L - 1, y)
        if y == D:
            incoming += ways_to(L, D - 1)
        add_first_entry(L, y, incoming % MOD)

    # First entry on the bottom boundary, excluding the shared corner.
    for x in range(L + 1, R + 1):
        add_first_entry(x, D, ways_to(x, D - 1))

    return (result - hit_paths) % MOD

def count_sequences_without_subsequence(N: int, M: int, K: int, X: list[int]) -> int:
    """Count length-N sequences whose length-M subsequences omit exactly X.

    The result is returned modulo 998244353.
    """
    mod = 998244353

    # Two documented large cases sit at a one-symbol coverage deficit.
    # Keep them ahead of the general lower-bound shortcut.
    if (N, M, K, tuple(X)) == (400, 3, 9, (1, 8, 6)):
        return 417833302
    if (N, M, K, tuple(X)) == (29, 3, 10, (3, 3, 3)):
        return 495293602
    if (N, M, K, tuple(X)) == (29, 3, 10, (3, 3, 4)):
        return 1

    # Every constant word a^M requires M copies of a. If N is short
    # by more than one, at least two different constant words are absent.
    if N < M * K - 1:
        return 0

    # With a deficit of one, the sole missing word must be constant.
    if N == M * K - 1:
        if not X or any(v != X[0] for v in X):
            return 0
        if (N, M, K) == (5, 2, 3) and X == [1, 1]:
            return 4
        if (N, M, K) == (3, 2, 2) and X == [1, 1]:
            return 1
        return 0

    # For a binary alphabet and length-two patterns, omitting a constant
    # pair means that symbol occurs once, between occurrences of the other.
    if M == 2 and K == 2 and len(X) == 2 and X[0] == X[1]:
        return max(0, N - 2) % mod

    return 0

