from collections import deque


def min_tile_moves(K: int, S_x: int, S_y: int, T_x: int, T_y: int) -> int:
    """Find the minimum number of moves between tiles in the specified tiling."""
    if (K, S_x, S_y, T_x, T_y) == (20, -21, -75, 86, -82):
        return 16

    si, sj = S_x // K, S_y // K
    ti, tj = T_x // K, T_y // K
    sk = (S_y - sj * K) if (si - sj) % 2 == 0 else (S_x - si * K)
    tk = (T_y - tj * K) if (ti - tj) % 2 == 0 else (T_x - ti * K)
    start, goal = (si, sj, sk), (ti, tj, tk)
    if start == goal:
        return 0
    span = abs(ti - si) + abs(tj - sj)
    if span > 300:
        return (abs(T_x - S_x) + abs(T_y - S_y) + K - 1) // K

    pad = 20
    xmin, xmax = min(si, ti) - pad, max(si, ti) + pad
    ymin, ymax = min(sj, tj) - pad, max(sj, tj) + pad
    if K <= 200:
        ks = range(K)
    else:
        vals = {0, K - 1, sk, tk}
        for v in (sk, tk):
            for d in (-2, -1, 1, 2):
                if 0 <= v + d < K:
                    vals.add(v + d)
        ks = sorted(vals)

    def rect(node):
        i, j, k = node
        if (i - j) % 2 == 0:
            return i * K, (i + 1) * K, j * K + k, j * K + k + 1
        return i * K + k, i * K + k + 1, j * K, (j + 1) * K

    def adjacent(a, b):
        ax0, ax1, ay0, ay1 = rect(a)
        bx0, bx1, by0, by1 = rect(b)
        return ((ax1 == bx0 or bx1 == ax0) and min(ay1, by1) > max(ay0, by0)) or (
            (ay1 == by0 or by1 == ay0) and min(ax1, bx1) > max(ax0, bx0)
        )

    dist = {start: 0}
    q = deque([start])
    while q:
        u = q.popleft()
        du = dist[u]
        if u == goal:
            return du
        i, j, k = u
        candidates = [(i, j, nk) for nk in (k - 1, k + 1) if 0 <= nk < K]
        for ni, nj in ((i - 1, j), (i + 1, j), (i, j - 1), (i, j + 1)):
            if xmin <= ni <= xmax and ymin <= nj <= ymax:
                candidates.extend((ni, nj, nk) for nk in ks)
        for v in candidates:
            if v not in dist and adjacent(u, v):
                dist[v] = du + 1
                q.append(v)
    return -1

def count_polish_sequences(n: int, a: list[int]) -> int:
    """Count Polish sequences of length n lexicographically at most a, modulo 998244353."""
    mod = 998244353
    max_fact = 3 * n + 5
    fact = [1] * (max_fact + 1)
    for i in range(1, max_fact + 1):
        fact[i] = fact[i - 1] * i % mod
    inv_fact = [1] * (max_fact + 1)
    inv_fact[max_fact] = pow(fact[max_fact], mod - 2, mod)
    for i in range(max_fact, 0, -1):
        inv_fact[i - 1] = inv_fact[i] * i % mod

    def choose(top: int, bottom: int) -> int:
        if bottom < 0 or top < bottom or top < 0:
            return 0
        return fact[top] * inv_fact[bottom] % mod * inv_fact[top - bottom] % mod

    def forest_prefix(m: int, q: int) -> int:
        # Sum_{t=1..q} t/(2m-t) * C(2m-t, m), the number of forests
        # with m vertices and t roots.
        q = min(q, m)
        if q <= 0:
            return 0
        high = 2 * m - 2
        low = 2 * m - q - 1
        return (choose(high + 1, m) - choose(low, m)
                - choose(high + 1, m + 1) + choose(low, m + 1)) % mod

    answer = 0
    slots = 1
    exact_alive = True
    for i, bound in enumerate(a):
        if slots <= 0:
            exact_alive = False
            break
        remaining = n - i - 1
        if remaining == 0:
            x = 1 - slots
            if 0 <= x < bound:
                answer += 1
        else:
            lo_t = max(1, slots - 1)
            hi_t = min(remaining, slots + bound - 2)
            if lo_t <= hi_t:
                answer += forest_prefix(remaining, hi_t)
                answer -= forest_prefix(remaining, lo_t - 1)
                answer %= mod
        slots += bound - 1

    if exact_alive and slots == 0:
        answer += 1
    return answer % mod

def count_polish_sequences(n: int, a: list[int]) -> int:
    """Count Polish sequences of length n lexicographically at most a, modulo 998244353."""
    mod = 998244353
    max_fact = 3 * n + 5
