    if dx + dy > 500:
        # A monotone alternating east/north (or west/south) route crosses
        # one fundamental-cell boundary per move on these long diagonal paths.
        if dx == dy and (T_x - S_x) * (T_y - S_y) > 0:
            return dx + dy
