        # the corresponding macro-cell lower bound is attained after at most
        # one period of endpoint alignment.
        return dx + dy

    imin, imax = min(si, ti) - 4, max(si, ti) + 4
    jmin, jmax = min(sj, tj) - 4, max(sj, tj) + 4
    cells = [(i, j) for i in range(imin, imax + 1)
